type Profil = { nama: string; email: string; umur: number };
type PesanGalat<T> = { [K in keyof T]?: string };

function validasi(p: Profil): PesanGalat<Profil> {
  const galat: PesanGalat<Profil> = {};
  if (p.nama.trim() === "") galat.nama = "Nama wajib diisi";
  if (!p.email.includes("@")) galat.email = "Email tidak valid";
  if (p.umur < 13) galat.umur = "Minimal 13 tahun";
  return galat;
}
const hasil = validasi({ nama: "Rina", email: "rina.contoh.id", umur: 12 });
console.log(Object.keys(hasil).join(","));
console.log(hasil.email);

