type Daftar = { nama: string; email: string; sandi: string };
type Galat<T> = { [K in keyof T]?: string };
type NamaKolom = `kolom-${keyof Daftar}`;
function idKolom(k: keyof Daftar): NamaKolom {
  return `kolom-${k}`;
}
function periksa(d: Daftar): Galat<Daftar> {
  const g: Galat<Daftar> = {};
  if (d.nama === "") g.nama = "Nama wajib diisi";
  if (d.sandi.length < 8) g.sandi = "Sandi minimal 8 karakter";
  return g;
}
const g = periksa({ nama: "", email: "rina@contoh.id", sandi: "123" });
console.log(Object.keys(g).join(","));
for (const k of Object.keys(g) as (keyof Daftar)[]) {
  console.log(idKolom(k) + ": " + g[k]);
}

