type JenisNilai<T> = T extends string ? "teks" : T extends number ? "angka" : "lain";
function jenis(x: string | number | boolean): string {
  return typeof x === "string" ? "teks" : typeof x === "number" ? "angka" : "lain";
}
const a: JenisNilai<"halo"> = "teks";
const b: JenisNilai<42> = "angka";
console.log(a, b, jenis(true));

