type Profil = { nama: string; email: string };
type Bendera<T> = { [K in keyof T]: boolean };
function diubah(lama: Profil, baru: Profil): Bendera<Profil> {
  return { nama: lama.nama !== baru.nama, email: lama.email !== baru.email };
}
const b = diubah({ nama: "Rina", email: "rina@contoh.id" }, { nama: "Rina", email: "rina.p@contoh.id" });
console.log("nama", b.nama, "email", b.email);
